   "explain": "】本题考查政治理论。 A 项，树立和践行正确政绩观，要健全有效防范和纠治政绩观偏差工作机制。“树牢竞争 优先，力争上游的政绩观”过于浮躁； B 项，政绩观正确与否，要看是否体现了全面发展。看政绩，既要看经济指标，也要看民 生指标、生态指标；既要看当前发展状况，也要看发展的可持续性。如果只盯着单 一指标，忽视其他工作，忽视发展的整体性、系统性、协同性，政绩观就会出现偏 差。因此B 项“要注重在做强发展指标，做优发展数据上下功夫”表述错误； C 项，树立和践行正确政绩观，坚持一切从实际出发，尽力而为、量力而行，合理规划、 有序推进办事项目。在办事过程中，要求真务实、苦干实干，力戒形式主义、官僚 ~ 7 ~ 全国服务电话：400-6353-606 主义，不搞劳民伤财的“形象工程”“政绩工程”，坚决纠正重“痕”不重“绩”、 留“迹”不留“心”等错误做法。故C 项发展“大气派工程”表述错误； D 项",
