   "q": "下列《三国演义》中的回目，按照先后顺序排列正确的是（ ）①宴长江曹操赋诗，锁战船北军用武②战官渡本初败绩，劫乌巢孟德烧粮③刘先主遗诏托孤儿，诸葛亮安居平五路④王司徒巧使连环计，董太师大闹凤仪亭",
