   "explain": "】本题考查人文常识。 ①“宴长江曹操赋诗，锁战船北军用武”出自《三国演义》第48 回，赤壁之战面对北方 军队不擅长水战，曹操在庞统的建议下，将战船用铁锁连接； ②“战官渡本初败绩，劫乌巢孟德烧粮”出自《三国演义》第30 回，官渡之战，曹操在 劫了乌巢后将其烧毁，断了袁绍的粮草； ③“刘先主遗诏托孤儿，诸葛亮安居平五路”出自《三国演义》第85 回，主要内容是刘 备在白帝城永安宫病重，召诸葛亮等人托付后事； ④“王司徒巧使连环计，董太师大闹凤仪亭”出自《三国演义》第8 回，主要内容是司 徒王允使用了连环计，将貂蝉许配给吕布，最后又将她献给了董卓。董卓在听闻吕 布约会貂蝉后，大闹了凤仪亭。按照先后顺序排列为④②①③。 故正确答案为D。",
