   "answer": 2,
   "explain": "】逻辑填空题。根据空后解释“这种结构开间大、立柱少，气势恢宏巍峨，可细分为 殿堂式与厅堂式，满足不同的礼制等级需要。”可知，空处应体现出能满足不同的礼制 等级需要，各种礼制等级都可以一直用这种结构。 A 项，“源远流长”比喻历史悠久，不符合文意，排除； B 项，“一枝独秀”比喻在同类人或同类事物中出类拔萃，不符合文意，排除； C 项，“一以贯之”比喻从一而终不会改变，可以一直用，符合文意，当选； D 项，“标新立异”比喻提出新的主张，不符合文意，排除。 故正确答案为C。",
