   "id": "xc-2025-gk-dishi-38",
   "module": "yanyu",
   "q": "兔和羚羊等食草动物获取食物时动作敏捷，牛类有瘤胃可以囤积食物，到一个安全的环境中再慢慢消化。大熊猫既没有敏捷度，也没有瘤胃结构，所以“______”选择了其他动物都不吃的食物种类，也出现了一些与进食、消化有关的基因突变，形成了一种独特性的食性——将箭竹作为主食。填入画横线部分最恰当的一项是（ ）",
