   "id": "xc-2025-gk-dishi-40",
   "module": "yanyu",
   "q": "党的规模大了，一些人容易出现搞小山头、小圈子、小团伙现象，容易出现______、自行其是问题，破坏党的团结统一，影响党的凝聚力战斗力。随着改革开放逐步深入，社会利益多元化、思想多样化也深刻影响到党员、干部的观念和行为。我们必须在重大问题、严峻形势面前始终心往一处想、劲往一处使，做到凝心聚力、______，确保全党紧密团结在党中央周围，步调一致向前进。依次填入画横线部分最恰当的一项是（ ）",
