   "q": "刺沙蓬也叫风滚草，一株可以携带约20 万粒种子。在随风滚动时，______的翻滚会帮助它抖落出种子，散落在地面上，时机成熟就会长成新的刺杀蓬，如此______。并且它们对水分的需求量较少，对盐度有较好的耐受性，在海滩、草原和沙漠等地方都能______生长。依次填入画横线部分最恰当的一项是（ ）",
