   "explain": "】语句排序题。选项出发，判断首句，首句不好判断。找捆绑，其中③句出现“才”， 相当于省略“只有”，是一个对策，⑥论述了严格执法和公正司法分别是什么，按照发展 逻辑，应该先引出话题，再提出对策，所以⑥在③前，排除A 项和C 项； 对比尾句，④和③，③句是对策，④句是问题的表述，所以④在③前，排除B 项。 故正确答案为D。",
