   "id": "xc-2025-gk-dishi-56",
   "module": "yanyu",
   "q": "相较于地球，月球上氦-3 储量极为丰富。氦-3 来源于太阳内部核聚变，以高能粒子形式通过太阳风向宇宙扩散。月球没有大气层，其磁场不足地球的千分之一，使得太阳风能够直射月球表面并将氦-3 注入月壤层。同时，月表温度在月夜最低可达-180℃，极地永久阴影区甚至可达-250℃。极低温环境有效促进了氦-3 被月壤吸附，并阻止其向太空散逸，并在月表不断富集。据估算，全月氦-3 换算储量高达110 万吨，可作为清洁核原料供地球使用约1 万年。这段文字能解释下列哪一问题（ ）",
