   "module": "yanyu",
   "q": "如果一味沉湎于琐碎的日常事务，缺乏大局观念和政治远见，不分轻重缓急，不从原则高度想问题，就会陷入事务主义，甚至由此滋生形式主义和官僚主义。习近平总书记指出：“如果忙忙碌碌，只是机械做事，陷入事务主义，是很难提高认识和工作水平的。”这就意味着，要提高认识水平，必须走出事务主义的泥潭。毛泽东曾经指出，“庸俗的事务主义家不是这样，他们尊重经验而看轻理论，因而不能通观客观过程的全体，缺乏明确的方针，没有远大的前途，沾沾自喜于一得之功和一孔之见。”这为如何走出事务主义泥潭提供了指南针和路线图。这段文字认为，为避免事务主义，应该（ ）~ 14 ~全国服务电话：400-6353-606",
