   "id": "xc-2025-gk-dishi-62",
   "module": "yanyu",
   "q": "如今，不少文艺工作者深入挖掘传统绘画与舞蹈之间的内在联系，将诗、书、画、乐、舞融为一体，形成新的审美表达。比如，杭州亚运会开幕式文艺表演环节，第一个节目《水墨入诗画》便以中国画为基本元素，身着青绿长裙的舞者在山水画卷中翩翩起舞，营造出“人在画中游”的意境。舞蹈诗剧《只此青绿》同样以经典的山水画为灵感，通过舞蹈再现王希孟创作《千里江山图》的过程，并以刚柔相济的肢体语言、精心设计的舞蹈动作呈现山水神韵。在这些作品中，传统绘画与舞蹈的创意融合产生叠加效应，使传统文化与现代审美相谐适，产生了广泛的社会影响。最适合做这段文字标题的是（ ）",
   "options": [
    "青绿热：传统与现代的双向奔赴",
    "传统与现代：审美表达的异与同",
    "画与舞：跨界融合激发艺术新活力",
    "人在画中游：穿越千年的艺术盛宴"
   ],
   "answer": 2,
   "explain": "】标题选择题。文段首句介绍“文艺工作者”将绘画与舞蹈联系，“形成新的审美表 达”，后文通过“比如”举例，论述《水墨入诗画》、《只此青绿》两部作品均是将传 统绘画与舞蹈进行巧妙融合，取得了很好的艺术效果，尾句“这些作品”对例子进行总 结，故整个文段为“观点+举例论证”，重在强调通过传统绘画与舞蹈的跨界融合，形 成了新的审美艺术表达，对应C 项。 A 项，“青绿热”对应文段举例部分的内容，非重点，且“传统与现代的双向奔赴”表 ~ 23 ~ 全国服务电话：400-6353-606 述错误，文段强调“传统绘画与舞蹈”的融合，排除； B 项，“传统与现代”表述不明确，文段重在强调“传统绘画与舞蹈”融合，产生了新 的审美艺术表达，且“审美表达的异与同”，非重点，排除； D 项，“人在画中游”对应文段举例部分的内容，非重点且表述片面，排除。 故正确答案为C。",
