   "module": "panduan",
   "q": "深度优先搜索是指从初始节点出发，按照一定的顺序扩展到下一个节点，然后从下一个节点出发继续扩展到新的节点，不断递归执行这个过程，直到某个节点不能再扩展到下一个节点，此时返回上一个节点重新寻找一个新的节点继续扩展，如此搜索下去，直到找到目标节点，或者搜索完所有节点为止。~ 25 ~全国服务电话：400-6353-606根据上述定义，如果以“1”为初始节点，“12”为目标节点，下列搜索路径符合深度优先搜索的是（ ）",
   "options": [
    "1→2→1→3→6→11→12",
    "1→4→8→4→1→3→6→12",
    "1→3→5→3→7→3→6→12",
    "1→3→5→10→5→3→1→3→6→12"
   ],
   "answer": 1,
   "explain": "】定义判断。关键词：从初始节点出发，按照一定的顺序扩展到下一个节点，从下一 个节点出发继续扩展到新的节点；某个节点不能再拓展到下一个节点；返回上一节点重 新寻找新的节点；直到找到目标节点。 A 项，从11 无法到12，此时应返回上一节点重新寻找新的节点，不符合定义，排除； B 项，1→4→8→4→1 符合直到某个节点不能再扩展到下一个节点，此时返回上一个节点 重新寻找新的节点，1→3→6→12 符合按照一定顺序扩展到下一个节点，直到找到 目标节点，符合定义，当选； C 项，1→3→5→3 不符合直到某个节点不能再扩展到下一个节点，此时返回上一个节点 重新寻找一个新的节点，不符合定义，排除； D 项，3→1→3，不符合直到某个节点不能再扩展到下一个节点，此时返回上一个节点重 新寻找一个新的节点继续扩展，不符合定义，排除。 故正确答案为B。",
