   "id": "xc-2025-gk-dishi-94",
   "module": "panduan",
   "q": "企业薪酬策略主要包括两个方面：一是体现企业支付标准的策略，即薪酬水平策略，其本质是在市场既定的薪酬水平上设定一个对公司有利的最优报酬水平；二是体现企业支付差异的策略，即薪酬结构策略，其通过企业的工资等级和工资幅度、加薪条件、晋升降级、小时工资、加班休假、工作时数时间等方面的薪酬政策表现出来。根据上述定义，下列说法正确的是（ ）",
   "options": [
    "甲企业根据市场调查结果，设定行政岗位的薪酬标准。这体现了薪酬结构策略",
    "乙企业今年赢利颇丰，企业将全员工资普遍调高。这体现了薪酬水平策略",
    "丙企业工资分为基本工资和绩效工资两部分，绩效工资与员工绩效挂钩。这体现了薪酬水平策略",
    "丁企业采取不同方式调整高、中、低三个职位层次人员的薪酬。这体现了薪酬水平策略"
   ],
   "answer": 1,
   "explain": "】定义判断。关键词：①薪酬水平策略：企业支付标准的策略、设定对公司有利的最 优报酬水平；②薪酬结构策略：通过企业一些方面的薪酬政策表现。 A 项，根据市场调查结果，设定岗位薪酬标准，属于设定对公司有利的最优报酬水平，符 合薪酬水平策略，不符合企业通过薪酬一些方面的薪酬政策表现，排除； B 项，将全员工资普遍调高，符合设定对公司有利的最优报酬水平，属于薪酬水平策略， 当选； C 项，将工资分为工资和绩效两部分，属于通过各种薪资政策表现，不属于薪资水平策 略，排除； D 项，调整高中低三个职位层次薪酬，体现了通过工资等级的薪酬政策表现，不属于薪 资水平策略，排除。 故正确答案为B。 ~ 32 ~ 全国服务电话：400-6353-606",
