   "q": "习近平总书记强调，加强党风廉政建设，一体推进不敢腐、不能腐、不想腐，严格落实中央八项规定精神，督促党员干部特别是领导干部清廉自守、廉洁从政。干净做事，根据《中国共产党纪律处分条例》下列违纪情形属于违反廉洁纪律的是（ ）",
