   "explain": "】逻辑填空题。第一空，空前出现“讲、不讲”反向并列关联词，前后语意相反，空 前强调“反映自己思考”，横线处要体现缺乏自己思考。 A 项，“故弄玄虚”指故意玩弄花招，叫人不可捉摸，不能体现缺乏自己思考，排除； B 项，“照本宣科”指死板地照现成文章或稿子宣读，不能灵活运用，能体现缺乏自己 的思考，保留； C 项，“人云亦云”指人家说什么自己也跟着说什么，形容没有主见，能体现缺乏自己 的思考，保留； D 项，“陈词滥调”指陈旧而不切合实际的话，与“话”语义重复，排除。 ~ 16 ~ 全国服务电话：400-6353-606 第二空，空前出现“讲、不讲”反向并列关联词，前后语意相反，空前强调“有感而 发”横线处要体现不是真正有所感悟的意思。 B 项，“无病呻吟”比喻没有值得忧虑的事情却长吁短叹，也比喻文艺作品缺乏真情实 感，矫揉造作，C 项，“言不由衷”意思是说的话不是从内心发出来的，指心口不 一",
