   "q": "甲和乙从环形跑道的同一点出发，向相反方向匀速慢跑。乙的速度是甲的一半。两人3 分钟后第一次相遇，此后乙加速又跑了正好半圈后和甲第二次相遇。问两人第一次到第二次相遇间隔了多长时间（ ）",
