   "q": "甲、乙、丙3 台收割机每小时均能收割2 亩小麦，三台机器上午先后开始收割工作。12:00时甲收割的面积是乙的1.5 倍，且比丙多收割6 亩。16:00 时3 台收割机共收割了50 亩。问乙是何时开始工作的（ ）",
