   "module": "shuliang",
   "q": "某种商品在定价基础上打八折销售，打折之前每天卖40 件，开始打折第一天起，每天都比前一天多卖10 件。打折销售 15 天的利润总额与打折之前销售20 天的利润相同。问这种商品的成本是定价的（ ）",
   "options": [
    "60%",
    "64%",
    "70%",
    "75%"
   ],
   "answer": 1,
   "explain": "】方程法。设定价为x，成本为y，所以打八折是0.8x，打折15 天的利润为（0.8x −y） × 40 × 15 元，打折后第一天卖40 + 10 = 50件，第15 天卖40 + 15 × 10 = 190件，所以 15 天一共卖出((50 + 190) × 15)/2 = 1800，打折之前的20 天利润为（x −y）× 1800 元，两种利润相同故（x −y）× 1800 = （0.8x −y）× 40 × 15，化简得640x = 1000y， x 所以 y = 64%。 故正确答案为B。",
