   "id": "xc-2025-gk-fsheng-91",
   "module": "panduan",
   "q": "后视错觉是个体的一种认知偏差，是指在一件事情已经发生之后，即使个体之前没有对此做过预判，也认为自己“早就知道会这样”。根据上述定义，下列符合后视错觉的是（ ）",
   "options": [
    "小瑾是一个悲观的人，她申请升职失败后，灰心丧气地说：“我早就知道，我什么都不如别人，什么也做不好。”",
    "朋友邀阿欣去爬山，阿欣说高温预警不宜爬山，朋友坚持去，才到半山腰就汗流浃背，阿欣说：“我早就说会很热啊。”",
    "晓琳参加一个重要会议迟到了。她懊悔地说：“我早该想到周一早上会堵车，不该按周末的情况预估通勤时间。”",
    "晓菲在股票大跌之后，懊恼地说：“我早就觉察到那些信号了，觉得走势不太好，怎么就没有早卖出啊。”"
   ],
   "answer": 2,
   "explain": "】定义判断。关键词：（1）事情已经发生后；（2）个体认为自己之前已经预见到结 果，尽管实际上并没有： A 项，小瑾说自己早就知道不如别人，什么都做不好，这更多反映出她的悲观性格和自 我认知，而不是对某件事情发生后认为自己早该知道的错觉，不符合定义，排除； B 项，阿欣在爬山前已经提出了高温预警不宜爬山的观点，这同样是一个事前的预判， 不符合定义，排除； C 项，晓琳懊悔地说她早该想到周一早上会堵车，表明她在事情发生前(即迟到前)没有 正确预估，但事后认为自己应该能够预见到。这符合后视错觉的定义，因为她实际 上并没有提前预判到堵车，但事后却认为自己“早就知道会这样”；符合关键词， 当选； D 项，晓菲说她早就察觉到信号觉得走势不好，这实际上是一个事前的预判，与后视错 觉的定义不符，因为她声称自己在事情发生前就有所察觉，不符合定义，排除。 故正确答案为C。",
