   "id": "xc-2025-gk-fsheng-93",
   "module": "panduan",
   "q": "选择或然率理论解释的是影响受众对大众传播内容选择的决定性因素。该理论的核心公式是：选择或然率=报偿的保证/费力的程度。其中，报偿的保证指的是传播内容满足选择者需要的程度，即内容对于受众的吸引力和实用性；费力的程度指的是获取传播内容和使用传播途径的难度。根据上述定义，下列属于提高选择或然率的传播行为的是（ ）",
   "options": [
    "视频号平台借助数据分析和个性化算法，给用户推荐符合其偏好的视频",
    "时下流行的某影视作品在播放之前被插入一段2 分钟的广告",
    "某商家优化了商品布局，将畅销商品放在出口处，顾客可直接扫码支付",
    "电视内置视频播放软件，开机后须先注册登录，才可搜索相关内容观看"
   ],
   "answer": 0,
   "explain": "】定义判断。关键词：选择或然率=报偿的保证/费力的程度；报偿的保证：传播内容 满足选择者需要的程度、内容对于受众的吸引力和实用性；费力的程度：获取传播内容 和使用传播途径的难度。 A 项，视频号平台借助数据分析和个性化算法给用户推荐符合其偏好的视频，这提高了 传播内容满足用户需要的程度，即提高了““报偿的保证”。因为用户能更容易看到自 己感兴趣的内容，而在获取内容方面没有增加难度，所以选择或然率会提高，符合 题干中关键词，当选； B 项，影视节目播放之前插入两分钟的广告，这增加了受众获取传播内容的难度，也就是 增加了““费力的程度”。观众需要花费额外的时间等待广告结束才能看到节目，这会 降低选择或然率，不符合题干中关键词，排除； C 项，商家优化商品布局，将畅销商品放在出口处，顾客可直接扫码支付。这样方便了顾 客获取商品，降低了““费力的程度”，但畅销商品可能对顾客有吸引力但实用性不能 确",
