   "id": "xc-2025-gk-fsheng-96",
   "module": "panduan",
   "q": "深度优先搜索是指从初始节点出发，按照一定的顺序扩展到下一个节点，然后从下一个节点出发继续扩展到新的节点，不断递归执行这个过程，直到某个节点不能再扩展到下一个节点，此时返回上一个节点重新寻找一个新的节点继续扩展，如此搜索下去，直到找到目标节点，或者搜索完所有节点为止。根据上述定义，如果以“1”为初始节点，“12”为目标节点，下列搜索路径符合深度优先搜索的是（ ）",
   "options": [
    "1→2→1→3→6→11→12",
    "1→4→8→4→1→3→6→12",
    "1→3→5→3→7→3→6→12",
    "1→3→5→10→5→3→1→3→6→12"
   ],
   "answer": 1,
   "explain": "】定义判断。关键词：从初始节点出发，按照一定的顺序不断扩展到下一个节点，直 到不能再扩展、此时返回上一个节点重新寻找一个新的节点继续扩展，直到找到目标节 点，或者搜索完所有节点为止。 A 项，图中显示，扩展到节点11 时已无法继续扩展，且未找到目标节点，此时应返回到 上一个节点6，而该项直接扩展到同级的节点12，不符合此时返回上一个节点重新 寻找一个新的节点继续扩展，如此搜索下去，直到找到目标节点，或者搜索完所有 节点为止，不符合定义，排除； B 项，图中显示，从初始节点1 出发，扩展到下一个节点4，继续扩展到下一个节点8， 此时已无法继续扩展，且未找到目标节点，应返回到上一个节点4，同理继续返回上 一个节点1，扩展到下一个节点3，继续扩展到下一个节点6，再扩展到下一个节点 12，此时已找到目标节点，搜索完成，符合从初始节点出发，按照一定的顺序不断 扩展到下一个节点，直到不能再扩展、此时返",
