   "answer": 1,
   "explain": "】加强论证。论点：第二种方案：“做浅”，在学校设立“冠名班”和“订单班”，以学 校教育为主，企业与学生当前没有签约意向，但随时保持互相选择的权利。 A 项，题干在讨论产教融合应该选择哪种方案，是否应该与学生签约，与付出人力成本 无关，论题不一致，排除； B 项，企业订单不稳定，订单突然增加时才需要大量人员，那么如果和学校签约“订单 班”，随时和学生互相选择，就能随时应对企业的用人需求，能支持选择第二方案， ~ 36 ~ 全国服务电话：400-6353-606 举例加强，可以加强，当选； C 项，企业生产使用特种专业设备，不具有从市场挖人的条件，与题干讨论的产教融合应 该选择哪种方案无关，是否应该与学生签约无关，论题不一致，排除； D 项，自建培训中心有利于企业保障准员工的培养质量，提前锁定毕业生，是在说第一 种方案更好，无法支持第二种方案，排除。 故正确答案为B。",
