   "id": "xc-2025-gk-fsheng-108",
   "module": "panduan",
   "q": "飞行信息记录系统，也就是俗标的黑匣子，在空难事故调查中的重要作用不需赘言，但无论在陆上还是海上的空难事故中，搜寻黑匣子都极其不易。有人建议，可利用现在飞速发展的互联技术，把黑匣子升级成为“云匣子”，那么飞机在空中就能够实时与地面进行信息交互，使空难事故的分析变得更加便捷。以下哪项如果为真，最能质疑上述建议（ ）",
