   "id": "xc-2025-gk-fsheng-115",
   "module": "panduan",
   "q": "甲、乙、丙、丁、戊、己、庚7 人报名参加象棋比赛，对于比赛结果，大家预测如下：（1）戊、己、庚至少有2 人获奖；（2）如果甲、丙、戊至少有1 人获奖，则丁、己均不获奖；（3）如果乙、戊、己至少有1 人获奖，则丁获奖而丙不获奖。比赛结束后，发现上述预测完全正确。根据上述信息，一定获奖的是（ ）",
