    "乙",
    "丙",
    "丁（共20 题，参考时限20 分钟）所给出的图、表、文字或综合性资料均有若干个问题要你回答。你应根据资料提供的信息进行分析、比较、计算和判断处理。请开始答题：材料一：截至2023 年末，我国集成电路布图设计等级累计申请93147 件，发证72378 件。2024~ 31 ~全国服务电话：400-6353-606年1—4 月，我国集成电路布图设计登记申请3503 件，发证4189 件。"
