   "q": "下列人物所说的话与经济有关，其中说法正确的是（ ）",
   "options": [
    "外资企业CEO：我公司的产值持续增长，为中国的GDP 提升做出了贡献",
    "社区居民：我的定期储蓄存款被统计在货币供应量M1 中",
    "留美学生：人民币汇率降低，我的学费也降低了",
    "纳税商户：相比于增值税，营业税的好处是避免重复征税"
   ],
   "answer": 0,
   "explain": "】本题考查经济常识。 A 项，国内生产总值（简称GDP）指在一定时期内（通常为一年），一个国家或地区的经 济中所产生出的全部最终产品和劳务的价值。无论企业是否为外资，只要其相关经 营活动在我国境内，其产值就计入我国GDP； B 项，中国货币供应量的层次划分为：M0=流通中现金；M1=M0+单位活期存款；M2=M1+ 单位定期存款+个人存款+其他存款。因此，定期存款属于M2； C 项，人民币汇率代表人民币的对外价值，当人民币汇率降低时，意味着人民币贬值，美 元相对升值。对于在美国留学的学生来说，这通常会导致他们需要支付更多的人民 币来兑换美元以支付学费； D 项，增值税只对产品或者服务的增值部分纳税，减少了重复纳税的环节。 故正确答案为A。",
   "year": 2025,
   "exam_type": "gk-xzf",
   "exam_volume": "行测",
   "topic": "",
   "src": "真题·PDF",
   "url": ""
