    "鱼类是这个时代的代言人，裸蕨在大地上站稳了脚跟，成片的森林改写了历史，登录的两栖类颠覆了乾坤——泥盆纪",
    "森林以裸子植物为名养育了恐龙，鸟类首次翱翔了天空，恐龙最终征服了世界——侏罗纪",
