   "explain": "】本题考查科技常识。志留纪是早古生代的最后一个纪，也是古生代第三个纪。约开 始于4.4 亿年前，结束于4.1 亿年前。志留纪的生物群特别是无脊椎动物类别更加繁多。 脊椎动物只有原始的无颌类。陆生植物的出现则是志留纪生物革新的一个重要标志。哺 乳动物成为地球主宰是在新生代。新生代（距今6500 万年）是地球历史上最新的一个地 质时代。随着恐龙的灭绝，中生代结束，新生代开始。新生代以哺乳动物和被子植物的 高度繁盛为特征。 故正确答案为D。",
