   "module": "yanyu",
   "q": "此前，司法机关获取救助线索主要靠人工摸排，这存在一定的______、被动性。为此，司法机关尝试运用大数据，主动发现救助线索，实现“应救尽救、应救即救”，同时衔接社会救助力量，构建多元帮扶机制，提供______救助，切实解决了一些困难群体急难愁盼的问题。依次填入画横线部分最恰当的一项是（ ）",
