   "module": "yanyu",
   "q": "各国正逐步形成以无人机、巡航导弹、弹道导弹、轰炸机等为主力的高效空袭体系，可以实现对目标空域的饱和袭击。这让只能命中单一目标的防空导弹陷入______的境地。面对复杂多样的战场威胁，防空导弹不再______，而是“攥指成拳”，朝着防空导弹系统升级转变。依次填入画横线部分最恰当的一项是（ ）",
