   "q": "①严格执法与公正司法是相辅相成的②加强行政执法与刑事司法衔接，是为了确保二者之间既能互不干扰，又能高效转换，从而更有力地实施法律③前端为后端减负、后端为前端增力，才能更好地让严格执法与公正司法共同发力，促进法律有效实施，保障社会公平正义④特别是在环境保护、食品安全、劳动保障等关系人民切身利益的重点领域，行政执法与刑事司法脱节会导致法律威慑力不足⑤习近平总书记指出：“要加强行政执法与刑事司法有机衔接，坚决克服有案不移、有案难移、以罚代刑等现象”⑥严格执法位于前端，通过行政手段依法保障人民群众的生命财产安全；公正司法位于后端，定分止争，是公平正义的最后一道防线将以上6 个句子重新排列，语序正确的是（ ）",
