   "module": "yanyu",
   "q": "由于缺乏现代科技手段，古代城市排水系统将依托地形、自流排水的理念贯穿在城市的规划和设计中，因此______。元朝时期，元大都的排水系统的规划设计与城市的总体布局同时进行，排水设施的建造先于城市或与城市道路、宫殿、城墙的建设同步，系统设计地下管网的高度差，充分发挥“水往低处流”的概念，使城市的内涝现象和污水溢出现象得到进一步缓解。元朝后，明清首都（北京）的排水格局也基本保持了元朝设计。填入画横线处，最恰当的一句话是（ ）",
