   "module": "yanyu",
   "q": "织纹螺主要分布于中国东南沿海，一般生活在近海礁石附近和泥沙底，自身并不产毒，其毒素来源于摄入带毒海藻。织纹螺使人中毒的毒素主要是麻痹性贝类毒素，其中的石房蛤毒素是目前已知毒性最强的海洋生物毒素之一，它通过阻断神经细胞膜中的钠通道而引起麻痹，毒性是眼镜蛇毒的80 倍；另外还有河豚毒素，这是自然界发现的毒性最强的神经毒素之一，其毒性比氰化钠还强1000 多倍，0.5 毫克即可致人死亡。这两种毒素的化学性质非常稳定，煮沸、盐腌、日晒等均不能将其破坏，所以吃上一颗织纹螺就可能致人死亡。下列说法中没有解释哪一问题（ ）~ 17 ~全国服务电话：400-6353-606",
