   "id": "xc-2025-gk-xzf-66",
   "module": "shuliang",
   "q": "甲乙丙3 台收割机每小时能收割2 亩小麦，三台机器上午先后开始收割工作，12：00 时甲收割的面积是乙的1.5 倍，且比丙多收割6 亩。16：00 三台收割机共收割了50 亩，问乙何时开始工作（ ）",
   "options": [
    "7:00",
    "6:00",
    "9:00",
    "8:00"
   ],
   "answer": 3,
   "explain": "】工程问题。甲乙丙三台机器下午同时从12：00 工作直到16：00，则三台机器工作效 率确定3 × 2 = 6。工作时间由12：00 到16：00，共四个小时，工作总量为三台机器总 效率乘以工作时间，6 × 4 = 24，下午工作量为24，则上午工作量为50 −24 = 26，此时 甲是乙的1.5 倍，且比丙多6，则可设乙为x，甲为1.5x，丙为1.5x −6，甲乙丙工作总量 为x + 1.5x + 1.5x −6 = 26，解得x = 8，则乙12 点时收割8 亩，根据时间等于工作总量 8 除以时间，则乙工作时间为 2 = 4。则乙从8：00 开始工作。 故正确答案为D。",
