   "module": "shuliang",
   "q": "张、王、李、赵，四人的平均年龄为28 岁，张王的年龄之和比李大25 岁，李赵的年龄之和比张大27 岁，已知张比王大2 岁，问他们四人中年龄最大的比最小的大几岁（ ）",
