   "id": "xc-2025-gk-xzf-94",
   "module": "panduan",
   "q": "断取是修辞格的一种，引用词语时，只截取其中部分字眼的意义，而置其余于不顾，是一种“断章取义”的修辞方式。根据上述定义，下列没有采用断取修辞方式的是（ ）",
   "options": [
    "相较于他之前见过的大阵仗，眼前的情形在他眼中就是“小儿科”",
    "小林一心扑在科研项目上，他至今还是一个“光杆司令”呢",
    "山林发生火灾，消防员“上刀山下火海”，奋力保卫人民的生命和财产安全",
    "实在走投无路，他最终还是找老师“开药方”，问询这一困局的破解之道"
   ],
   "answer": 3,
   "explain": "】定义判断。选非题。关键词：只截取其中部分字眼的意义，而置其余于不顾。 A 项，引用“小儿科”时，只取“小”义而舍“儿科”义，表明了眼前的情形在他眼中只 是小阵仗，符合只截取其中部分字眼的意义，而置其余于不顾，符合定义，排除； B 项，引用“光杆司令”时，只取“光杆”义而舍“司令”义，表明了小林因搞科研而至 今未成婚，仍独身一人，符合只截取其中部分字眼的意义，而置其余于不顾，符合 定义，排除； C 项，引用“上刀山下火海”时，只取“下火海”义而舍“上刀山”义，突出了消防员在 扑救大火时不畏艰难险阻的勇敢精神，符合只截取其中部分字眼的意义，而置其余 于不顾，符合定义，排除； D 项，引用“开药方”时，用了其完整的意思，表明了他在走投无路时，找老师寻求解决 方法，不符合只截取其中部分字眼的意义，而置其余于不顾，不符合定义，当选。 故正确答案为D。",
   "year": 2025,
   "exam_type": "gk-xzf",
   "exam_volume": "行测",
   "topic": "",
   "src": "真题·PDF",
